@router.get("/low-stock")
def low_stock(below: int) -> list[LowStock]:
    if not 1 <= below <= 1000:
        raise InvalidRequest("below is between 1 and 1000")
    with transaction() as conn:
        products = [p for p in all_products(conn) if p.stock < below]
    products.sort(key=lambda p: (p.stock, p.sku))
    return [LowStock(sku=p.sku, name=p.name, stock=p.stock) for p in products]


@router.patch("/products/{sku}/stock")
def restock(sku: str, body: Restock) -> Product:
    if body.amount <= 0:
