import { api, attempt, type Schemas } from "../api/client";
import type { Outcome } from "./result";

export type Address = Schemas["Address"];

/** A user's default shipping address, or null when none has been set. */
export async function getDefaultAddress(baseUrl: string, email: string): Promise<Outcome<Address | null>> {
  const outcome = await attempt(() =>
    api(baseUrl).GET("/users/{email}/default-address", { params: { path: { email } } }),
  );
  if (!outcome.ok) return outcome;
  return { ok: true, value: outcome.value ?? null };
}
