import { api, attempt } from "../api/client";
import type { Outcome } from "./result";

const STATUSES = ["open", "paid", "cancelled"] as const;
type Status = (typeof STATUSES)[number];

function isStatus(status: string): status is Status {
  return (STATUSES as readonly string[]).includes(status);
}

/** How many of a customer's orders have a status. */
export async function countOrders(baseUrl: string, email: string, status: string): Promise<Outcome<number>> {
  if (!isStatus(status)) {
    return { ok: false, error: { kind: "ValidationError", rule: "status is open, paid or cancelled" } };
  }
  return attempt(() => api(baseUrl).GET("/orders/count", { params: { query: { email, status } } }));
}
